  "track.kotlin.m.smartcast.s.lambdaVar.rule.explain": "Lambda có thể chạy bất cứ lúc nào (kể cả giữa lúc kiểm và lúc dùng), nên trình biên dịch không bảo đảm được note vẫn khác null.",
  "track.kotlin.m.smartcast.ev.lambdaVar.rule": "var cục bộ bị lambda sửa: không",
  "track.kotlin.m.smartcast.s.lambdaVar.use.title": "Lỗi biên dịch ở note.length",
